import numpy as np, json
def read_xyz(p):
    lines = open(p).read().split('\n')
    n = int(lines[0]); els=[]; xyz=[]
    for l in lines[2:2+n]:
        t=l.split(); els.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return els, np.array(xyz)
els, xyz = read_xyz('init2.xyz')
ix = json.load(open('idx.json'))
Cr1, Cr2 = ix['Cr1'], ix['Cr2']
def d(a,b): return np.linalg.norm(xyz[a]-xyz[b])
print('Cr-Cr', round(d(Cr1,Cr2),2))
for name in ['O1','O2','O3','O4']:
    o = ix[name]
    print(name, 'Cr1', round(d(Cr1,o),2), 'Cr2', round(d(Cr2,o),2))
for rn, cr in [('B',Cr1),('Fring',Cr2)]:
    c = xyz[ix[rn]].mean(0)
    print(rn,'centroid dist Cr1', round(np.linalg.norm(xyz[Cr1]-c),2), 'Cr2', round(np.linalg.norm(xyz[Cr2]-c),2))
    for a in ix[rn]:
        print('   ', a, round(np.linalg.norm(xyz[cr]-xyz[a]),2))
